$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path

function Require-Text([string]$path, [string]$needle) {
    $text = Get-Content -Raw (Join-Path $root $path)
    if (-not $text.Contains($needle)) { throw "Missing '$needle' in $path" }
}

function Reject-Text([string]$path, [string]$needle) {
    $text = Get-Content -Raw (Join-Path $root $path)
    if ($text.Contains($needle)) { throw "Forbidden '$needle' in $path" }
}

