$compatRoot = Join-Path $root 'app\src\main\assets\rgss_compat'
if (-not (Test-Path (Join-Path $compatRoot 'common\win32_wrap.rb'))) { throw 'win32_wrap asset missing' }
if (-not (Test-Path (Join-Path $compatRoot 'common\mkxp_wrap.rb'))) { throw 'mkxp_wrap asset missing' }
if (-not (Test-Path (Join-Path $compatRoot 'common\ruby_classic_wrap.rb'))) { throw 'ruby_classic_wrap asset missing' }
if (-not (Test-Path (Join-Path $compatRoot 'common\native_ext_compat.rb'))) { throw 'native_ext_compat asset missing' }
if (-not (Test-Path (Join-Path $compatRoot 'common\fix_volume.rb'))) { throw 'fix_volume asset missing' }
if (-not (Test-Path (Join-Path $compatRoot 'cicpoffs\ports\mouse_skip.rb'))) { throw 'mouse_skip asset missing' }
if (-not (Test-Path (Join-Path $compatRoot 'common\cicpoffs_compat.rb'))) { throw 'cicpoffs_compat asset missing' }
$compatFiles = @(Get-ChildItem $compatRoot -Recurse -File)
if ($compatFiles.Count -lt 30) { throw "RGSS compat asset set too small: $($compatFiles.Count)" }

$font = Join-Path $root 'app\src\main\assets\fonts\wqymicrohei.ttf'
if (-not (Test-Path $font)) { throw 'Korean fallback font asset missing' }
if ((Get-Item $font).Length -lt 4000000) { throw 'Korean fallback font asset unexpectedly small' }
foreach ($mk in @(
    'vendor\mkxp-z-android-mtool-reference\app\jni\mkxp-z-187.mk',
    'vendor\mkxp-z-android-mtool-reference\app\jni\mkxp-z-193.mk',
    'vendor\mkxp-z-android-mtool-reference\app\jni\mkxp-z.mk'
)) {
    Require-Text $mk 'MKXPZ_CJK_FONT'
}

Require-Text 'vendor\android-mkxp-reference\app\src\main\jni\mkxp\binding-mri\binding-mri.cpp' 'RPGMP_ANDROID_CICPOFFS_PRE_EVAL'
Require-Text 'vendor\android-mkxp-reference\app\src\main\jni\mkxp\binding-mri\binding-mri.cpp' 'compat/common/cicpoffs_compat.rb'

foreach ($probe in @('libprobe-ruby18.so','libprobe-ruby19.so','libprobe-ruby31.so')) {
    $probePath = Join-Path $root ('app\src\main\jniLibs\arm64-v8a\' + $probe)
    if (-not (Test-Path $probePath)) { throw "Ruby probe missing: $probe" }
    if ((Get-Item $probePath).Length -lt 1000000) { throw "Ruby probe unexpectedly small: $probe" }
}

Write-Output 'ANDROID_STORAGE_RUNNER_SMOKE_PASS'
Write-Output ("RGSS_COMPAT_ASSET_COUNT=" + $compatFiles.Count)
